head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 반환합니다.",
    "validation" : [
        "Body Cell 의 imageSrc 속성값은 setCellImageSrc() 메소드로 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터로 imageSrc 속성값을 조회할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정되어야 합니다.",
        "columnInfo(필수) 파라미터로 imageSrc 속성값을 조회할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정되어야 합니다.",
        "파라미터에 해당하는 Body Cell 의 imageSrc 속성값을 반환해야 합니다.",
        "setCellImageSrc() 메소드로 설정한 Body Cell 의 imageSrc 속성값을 반환하며 Column 단위의 imageSrc 속성값을 반환하지 않아야 합니다.",
        "해당 Body Cell 의 imageSrc 속성에 설정된 값이 없으면 undefined 를 반환해야 합니다.",
        "imageSrc 속성값이 ''(Empty String)인 경우 유효하게 설정된 값으로 반환되어야 합니다.",
        "setCellImageSrc() 메소드로 특정 Body Cell 의 imageSrc 속성이 설정된 경우 Column 보다 Body Cell 의 imageSrc 속성이 우선 적용되어야 합니다.",
        "setImageSrc() 메소드로 Column 의 imageSrc 속성값을 변경해도 Body Cell 의 imageSrc 속성값은 변경되지 않으므로 getCellImageSrc() 메소드의 반환값은 변하지 않아야 합니다.",
        "Column 의 inputType='textImage', viewType='icon' 인 경우에 Body Cell 의 유효한 imageSrc 속성값을 반환해야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_rowIndex.setSelectedIndex(0);
    par_columnInfo.setSelectedIndex(2);
    par_imageSrc.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(정의 인덱스) : 0 name(text) / 1 hid(textImage+icon, 숨김) / 2 timg(textImage+icon, Column imageSrc 설정) / 3 timg2(textImage+icon, Column imageSrc 미설정)
//    · 인덱스 1 을 setColumnVisible(1, false) 로 숨김 → 숨겨진 Column 도 인덱스에 포함되므로
//      화면상 두번째로 보이는 timg 의 Column 인덱스는 2 가 됨
//    · 2 timg  : Column 단위 imageSrc 를 설정 → Cell 미설정 상태에서 undefined 가 반환되는지(@return) 확인용
//    · 3 timg2 : @spec3 (inputType='textImage', viewType='icon') 충족 Column → 유효한 imageSrc 반환 확인용
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 구성(인덱스) : 0 = name(text) / 1 = hid(textImage+icon, setColumnVisible 로 숨김) / 2 = timg(textImage+icon, Column 단위 imageSrc = /cm/images/base/ico_grid_del.svg 설정) / 3 = timg2(textImage+icon, Column 단위 imageSrc 미설정)\n[절차] rowIndex / columnInfo / imageSrc 를 선택하고 getCellImageSrc 버튼으로 현재 반환값을 확인한 뒤, setCellImageSrc 버튼으로 Cell 값을 설정하고 다시 getCellImageSrc 버튼을 클릭하세요.\n[절차] setImageSrc 버튼은 먼저 setCellImageSrc 로 Cell 값을 설정한 상태에서 클릭해야 Column 값 변경 전후의 반환값을 비교할 수 있습니다.\n[확인] 결과창의 반환값 표기에서 undefined 와 빈 문자열(Empty String)이 구분되는지, 화면상 두번째로 보이는 timg Column 을 인덱스 2 로 조회하는지 확인하세요."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="hid" name="hid" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg2" name="timg2" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "hid": "H0", "timg": "수정", "timg2": "보기" },
        { "name": "Jane", "hid": "H1", "timg": "수정", "timg2": "보기" },
        { "name": "Mike", "hid": "H2", "timg": "수정", "timg2": "보기" },
        { "name": "Amy",  "hid": "H3", "timg": "수정", "timg2": "보기" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:640px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getCellImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="name (0, text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="hid (1, 숨김)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol3" value="timg (2, textImage+icon)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="timg2 (3, textImage+icon)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="textImage" viewType="icon" id="hid" dataList="hid"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="timg" dataList="timg"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="timg2" dataList="timg2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1 (hid) 숨김 → 숨겨진 Column 도 인덱스에 포함됨을 검증
    target1.setColumnVisible(1, false);
}



// 반환값을 undefined / ''(Empty String) / 일반 문자열이 구분되도록 표기
scwin.fmtReturn = function (value) {
    if (value === undefined) {
        return "undefined (설정된 값 없음)";
    }
    if (value === null) {
        return "null";
    }
    if (typeof value === "string") {
        return (value === "") ? "'' (Empty String, String 타입 유효값)" : "'" + value + "'";
    }
    return String(value);
}



// Cell 에 실제 표시된 이미지 경로 확인
scwin.getCellImgSrc = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    if (!imgEl || !imgEl.getAttribute("src")) {
        return "(이미지 미표시)";
    }
    return imgEl.getAttribute("src");
}



scwin.getParamImageSrc = function () {
    let text = par_imageSrc.getText();
    return (text === "(Empty String)") ? "" : text;
}



// getCellImageSrc : 검증 대상 API
scwin.btn_getCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());

    let rtn = target1.getCellImageSrc(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + scwin.fmtReturn(rtn));
    wf_body_bottom.getObj("scwin").setReturnValue("화면 Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));
}



// setCellImageSrc : getCellImageSrc 의 반환값을 만들기 위한 전제 설정용
scwin.btn_setCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());
    let imageSrc = scwin.getParamImageSrc();

    target1.setCellImageSrc(rowIndex, columnInfo, imageSrc);

    wf_body_bottom.getObj("scwin").setReturnValue("[전제 설정] setCellImageSrc(" + rowIndex + ", " + columnInfo + ", " + scwin.fmtReturn(imageSrc) + ") 실행");
}



// setImageSrc : Column 단위 imageSrc 변경 시 getCellImageSrc 반환값이 불변인지 확인 (@spec2)
scwin.btn_setImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());
    let imageSrc = scwin.getParamImageSrc();

    let before = target1.getCellImageSrc(rowIndex, columnInfo);
    target1.setImageSrc(columnInfo, imageSrc);
    let after = target1.getCellImageSrc(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("setImageSrc 호출 전 getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + scwin.fmtReturn(before));
    wf_body_bottom.getObj("scwin").setReturnValue("setImageSrc 호출 후 getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + scwin.fmtReturn(after));
}
